#!/usr/bin/env node

import { createClient } from '../dist/esm/index.js';

const args = process.argv.slice(2);
const features = [];
let mac;

for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];

    if (argument === '--help' || argument === '-h') {
        console.log('Usage: dhcp [hostname dns router ...] [--mac 12:34:56:78:90:AB]');
        process.exit(0);
    }
    if (argument === '--mac') {
        mac = args[index += 1];
        if (!mac) {
            throw new Error('--mac requires a value');
        }
    } else if (argument.startsWith('--')) {
        throw new Error(`Unknown option: ${argument}`);
    } else {
        features.push(argument);
    }
}

const client = createClient({
    mac,
    features,
});

client.on('bound', (lease) => {

    for (const [key, value] of Object.entries(lease.options)) {
        console.log(`${key}: ${Array.isArray(value) ? value.join(', ') : value}`);
    }
    client.close(() => process.exit(0));
});
client.listen(() => client.sendDiscover());
